# Proper test - compare full rows
def transform(grid):
    g=[row[:] for row in grid]
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    pat=set(cnt)-{bg}
    pat={c for c in pat if c!=2} or {2}
    for r in g:
        idx=[i for i,x in enumerate(r) if x in pat]
        for a,b in zip(idx,idx[1:]):
            for i in range(a+1,b):
                if r[i]==bg:
                    r[i]=2
    return g

